import raw from "@/data/india-locations.json";

/**
 * Static India location data — all 36 states / union territories plus their
 * cities — generated by `scripts/build-india-locations.mjs`.
 *
 * Kept as plain data (no network calls) so onboarding stays fast and works
 * offline. Lookups are case-insensitive so a value saved before this list
 * existed still matches.
 */
export const INDIAN_STATES: readonly string[] = raw.states;

const CITIES_BY_STATE = raw.citiesByState as Record<string, readonly string[]>;

const STATE_LOOKUP = new Map<string, string>(
  INDIAN_STATES.map((state) => [state.trim().toLowerCase(), state]),
);

/** Canonical state name for any casing/spelling we know; otherwise undefined. */
export function findState(
  value: string | null | undefined,
): string | undefined {
  const trimmed = (value ?? "").trim().toLowerCase();
  if (!trimmed) return undefined;
  return STATE_LOOKUP.get(trimmed);
}

export function isIndianState(value: string | null | undefined): boolean {
  return findState(value) !== undefined;
}

/** Cities belonging to a state. Empty when the state is blank/unknown. */
export function citiesForState(
  state: string | null | undefined,
): readonly string[] {
  const canonical = findState(state);
  if (!canonical) return [];
  return CITIES_BY_STATE[canonical] ?? [];
}
